{"command":"cat <<'EOF' > test_long_args.py
import subprocess
import re

out = subprocess.check_output("curl --help all", shell=True).decode()
long_opts = []
for line in out.split("\n"):
    m = re.search(r'--([a-zA-Z0-9-]+)', line)
    if m:
        long_opts.append(m.group(1))

long_opts = list(set(long_opts))

with_args = []
without_args = []

for opt in long_opts:
    try:
        p = subprocess.Popen(f"./executable --curl --{opt} url", shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        out, err = p.communicate()
        if b"http://url" not in err:
            with_args.append(opt)
    except Exception:
        pass

print("With args:", sorted(with_args))
EOF
