{"command":"cat <<'EOF' > test_pretty.go
package main
import (
    "bytes"
    "fmt"
)

func isAlnum(c byte) bool {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E'
}

func isNumber(s []byte) bool {
    if len(s) == 0 { return false }
    return (s[0] >= '0' && s[0] <= '9') || s[0] == '-'
}

func PrettyPrint(in []byte) []byte {
    var out bytes.Buffer
    indent := 0
    isValue := false
    out.WriteString("\x1b[37m") // start with white
    for i := 0; i < len(in); i++ {
        c := in[i]
        switch c {
        case ' ', '\n', '\r', '\t':
            continue
        case '{', '[':
            isValue = false
            indent += 4
            out.WriteString(string(c))
            out.WriteString("\n")
            for j := 0; j < indent; j++ { out.WriteByte(' ') }
        case '}', ']':
            indent -= 4
            out.WriteString("\n")
            for j := 0; j < indent; j++ { out.WriteByte(' ') }
            out.WriteString("\x1b[37m")
            out.WriteString(string(c))
            isValue = false
        case ',':
            isValue = false
            out.WriteString("\x1b[37m,\n")
            for j := 0; j < indent; j++ { out.WriteByte(' ') }
        case ':':
            isValue = true
            out.WriteString("\x1b[37m: ")
        case '"':
            // string
            start := i
            i++
            for i < len(in) {
                if in[i] == '\\' {
                    i += 2
                    continue
                }
                if in[i] == '"' {
                    break
                }
                i++
            }
            str := in[start : i+1]
            if !isValue {
                out.WriteString("\x1b[34m")
                out.Write(str)
                out.WriteString("\x1b[37m")
            } else {
                out.WriteString("\x1b[36m")
                out.Write(str)
                // no revert, next punctuation will revert
            }
        default:
            // number or boolean
            start := i
            for i < len(in) && isAlnum(in[i]) {
                i++
            }
            str := in[start:i]
            i--
            if !isValue {
                // uncolored -> just print
                out.Write(str)
            } else {
                if isNumber(str) {
                    out.WriteString("\x1b[36m")
                } else {
                    out.WriteString("\x1b[35m")
                }
                out.Write(str)
            }
        }
    }
    out.WriteString("\n\x1b[0m")
    return out.Bytes()
}

func main() {
    cases := []string{
        `{"a": "b"}`,
        `["a", "b"]`,
        `[1, 2]`,
        `{"a": [1, 2]}`,
        `{"a": 1, "b": 2}`,
        `{"a": true}`,
        `[true, false, null]`,
        `{"a": {"b": 1}}`,
        `[{}]`,
    }
    for _, c := range cases {
        fmt.Printf("%q\n", string(PrettyPrint([]byte(c))))
    }
}
EOF
go run test_pretty.go"}

