{"command":"cat <<'EOF' > tidy_pretty.go
package main
import "fmt"

func appendString(dst []byte, s string) []byte {
	return append(dst, s...)
}

func Pretty(json []byte) []byte {
	var dst []byte
	indent := 0
	inString := false
	var escape bool
	for i := 0; i < len(json); i++ {
		c := json[i]
		if inString {
			dst = append(dst, c)
			if escape {
				escape = false
			} else if c == '\\' {
				escape = true
			} else if c == '"' {
				inString = false
			}
			continue
		}
		if c == '"' {
			inString = true
			dst = append(dst, c)
			continue
		}
		if c == ' ' || c == '\n' || c == '\r' || c == '\t' {
			continue
		}
		if c == '{' || c == '[' {
			dst = append(dst, c, '\n')
			indent += 4
			for j := 0; j < indent; j++ {
				dst = append(dst, ' ')
			}
			continue
		}
		if c == '}' || c == ']' {
			indent -= 4
			dst = append(dst, '\n')
			for j := 0; j < indent; j++ {
				dst = append(dst, ' ')
			}
			dst = append(dst, c)
			continue
		}
		if c == ',' {
			dst = append(dst, c, '\n')
			for j := 0; j < indent; j++ {
				dst = append(dst, ' ')
			}
			continue
		}
		if c == ':' {
			dst = append(dst, c, ' ')
			continue
		}
		dst = append(dst, c)
	}
	return dst
}

func main() {
    fmt.Printf("%q\n", string(Pretty([]byte("[{}]"))))
}
EOF
go run tidy_pretty.go"}

