package main
import (
	"fmt"
	"io"
	"os"
)

func isAlnum(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E'
}
func isNumber(s []byte) bool {
	if len(s) == 0 { return false }
	return (s[0] >= '0' && s[0] <= '9') || s[0] == '-'
}

type PrettyWriter struct {
	w       io.Writer
	indent  int
	isValue bool
	inStr   bool
	escape  bool
	buf     []byte
}

func (p *PrettyWriter) writeIndent() {
	for i := 0; i < p.indent; i++ {
		p.w.Write([]byte{' '})
	}
}

func (p *PrettyWriter) Write(b []byte) (int, error) {
	// actually for a streaming writer, buffering incomplete tokens (like strings, keywords) is tricky!
	// if we split a chunk inside "false", we wouldn't color it correctly.
	// But tidwall/pretty converts the WHOLE byte slice, or it provides a streaming pretty printer?
	// tidwall/pretty has NO streaming API! It takes `[]byte` and returns `[]byte`!
	// So does curlie actually buffer? "Output is not buffered; formatting is done on the fly"
	// Wait, rs/curlie uses `github.com/TylerBrock/colorjson` ? No, colorjson unmarshals!
	return len(b), nil
}

func main() {
    fmt.Println("ok")
}
