package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
)

// Fake Pretty and Color implementations
func Pretty(json []byte) []byte {
	return json // we know the real implementation
}
func Color(json []byte) []byte {
	return append([]byte("\x1b[37m"), append(json, []byte("\n\x1b[0m")...)...)
}

func PrintStream(r io.Reader) {
	dec := json.NewDecoder(r)
	for {
		var raw json.RawMessage
		err := dec.Decode(&raw)
		if err != nil {
			// Print whatever was buffered + the rest of the stream
			if buffered, err := io.ReadAll(dec.Buffered()); err == nil {
				os.Stdout.Write(buffered)
			}
			io.Copy(os.Stdout, r)
			break
		}
		// SUCCESS! Format and color!
		os.Stdout.Write(Color(Pretty(raw)))
	}
}

func main() {
    PrintStream(os.Stdin)
}
