}

func shellQuote(s string) string {
	if strings.ContainsAny(s, " \t\n\r") {
		return fmt.Sprintf("%q", s)
	}
	return s
}

func isMethod(arg string) bool {
	u := strings.ToUpper(arg)
	switch u {
	case "GET", "POST", "PUT", "DELETE", "HEAD", "OPTIONS", "PATCH", "TRACE":
		return true
	}
	return false
}

func colorHeader(text string, isReq bool) {
	if strings.HasPrefix(text, "HTTP/") {
		parts := strings.SplitN(text, " ", 3)
		if len(parts) >= 3 {
			ver := parts[0][5:]
			code := parts[1]
			msg := parts[2]
			fmt.Fprintf(os.Stderr, "\x1b[34mHTTP\x1b[37m/\x1b[36m%s %s\x1b[33m %s\x1b[0m\n", ver, code, msg)
		} else {
			fmt.Fprint(os.Stderr, text, "\n")
		}
	} else if idx := strings.Index(text, ":"); idx != -1 {
		key := text[:idx+1]
		val := text[idx+1:]
		fmt.Fprintf(os.Stderr, "\x1b[37m%s\x1b[36m%s\x1b[0m\n", key, val)
	} else {
		parts := strings.SplitN(text, " ", 3)
		if len(parts) >= 3 && strings.HasPrefix(parts[2], "HTTP/") {
			method := parts[0]
			path := parts[1]
			ver := parts[2][5:]
			fmt.Fprintf(os.Stderr, "\x1b[34m%s\x1b[37m %s \x1b[34mHTTP\x1b[37m/\x1b[36m%s\x1b[0m\n", method, path, ver)
		} else {
			fmt.Fprint(os.Stderr, text, "\n")
		}
	}
}

func processStderr(r io.Reader, flagPretty bool, hasV bool, requestBody []byte) {
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "* ") {
			if hasV {
				if flagPretty {
					fmt.Fprintf(os.Stderr, "\x1b[90m%s\x1b[0m\n", line)
				} else {
					fmt.Fprintln(os.Stderr, line)
				}
			}
		} else if strings.HasPrefix(line, "> ") {
			if hasV {
				text := line[2:]
				if text == "\r" {
					fmt.Fprint(os.Stderr, "\r\n")
					if len(requestBody) > 0 {
						if flagPretty {
							fmt.Fprintf(os.Stderr, "%s\n\n", string(PrettyColor(requestBody)))
						} else {
							fmt.Fprintf(os.Stderr, "%s\n\n", string(requestBody))
						}
					}
				} else {
					if flagPretty {
						colorHeader(text, true)
					} else {
						fmt.Fprintln(os.Stderr, text)
					}
				}
			}
		} else if strings.HasPrefix(line, "< ") {
			if hasV || flagPretty {
				text := line[2:]
				if text == "\r" {
					fmt.Fprint(os.Stderr, "\r\n")
				} else {
					if flagPretty {
						colorHeader(text, false)
					} else {
						fmt.Fprintln(os.Stderr, text)
					}
				}
			}
		} else if strings.HasPrefix(line, "} [") || strings.HasPrefix(line, "{ [") {
			// ignore
		} else {
			if flagPretty && strings.HasPrefix(line, "curl: ") {
				fmt.Fprintf(os.Stderr, "\x1b[31m%s\x1b[0m\n", line)
			} else {
				fmt.Fprintln(os.Stderr, line)
			}
		}
	}
}

func main() {
	var curlOpts []string
	var method string
	var url string
	var items map[string]interface{} = make(map[string]interface{})
	var hasData bool
	var itemsOrHeaders []string

	flagCurl := false
	flagPretty := false

	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]
		if arg == "--curl" {
			flagCurl = true
			continue
		}
		if arg == "--pretty" {
			flagPretty = true
			continue
		}

		if strings.HasPrefix(arg, "--") && len(arg) > 2 {
