func processStderr(r io.Reader, flagPretty bool, hasV bool, requestBody []byte) {
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "* ") {
			if hasV {
				if flagPretty {
					fmt.Fprintf(os.Stderr, "\x1b[90m%s\x1b[0m\n", line)
				} else {
					fmt.Fprintln(os.Stderr, line)
				}
			}
		} else if strings.HasPrefix(line, "> ") {
			if hasV {
				text := line[2:]
				if text == "\r" {
					fmt.Fprint(os.Stderr, "\r\n")
					if len(requestBody) > 0 {
						if flagPretty {
							fmt.Fprintf(os.Stderr, "%s\n\n", string(PrettyColor(requestBody)))
						} else {
							fmt.Fprintf(os.Stderr, "%s\n\n", string(requestBody))
						}
					}
				} else {
					if flagPretty {
						colorHeader(text, true)
					} else {
						fmt.Fprintln(os.Stderr, text)
					}
				}
			}
		} else if strings.HasPrefix(line, "< ") {
			if hasV || flagPretty {
				text := line[2:]
				if text == "\r" {
					fmt.Fprint(os.Stderr, "\r\n")
				} else {
					if flagPretty {
						colorHeader(text, false)
					} else {
						fmt.Fprintln(os.Stderr, text)
					}
				}
			}
		} else if strings.HasPrefix(line, "} [") || strings.HasPrefix(line, "{ [") {
			// ignore
		} else {
			if flagPretty && strings.HasPrefix(line, "curl: ") {
				fmt.Fprintf(os.Stderr, "\x1b[31m%s\x1b[0m\n", line)
			} else {
				fmt.Fprintln(os.Stderr, line)
			}
		}
	}
}

func main() {
	var curlOpts []string
	var method string
	var url string
	var items map[string]interface{} = make(map[string]interface{})
	var hasData bool
	var itemsOrHeaders []string

	flagCurl := false
	flagPretty := false

	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]
		if arg == "--curl" {
			flagCurl = true
			continue
		}
		if arg == "--pretty" {
			flagPretty = true
			continue
		}

		if strings.HasPrefix(arg, "--") && len(arg) > 2 {
			parts := strings.SplitN(arg[2:], "=", 2)
			opt := parts[0]
			curlOpts = append(curlOpts, arg)
			if len(parts) == 1 && isLongArg(opt) && i+1 < len(os.Args) {
				i++
				curlOpts = append(curlOpts, os.Args[i])
			}
			continue
		}
		if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			for j := 1; j < len(arg); j++ {
				c := arg[j]
				if isShortArg(c) {
					if j+1 < len(arg) {
						curlOpts = append(curlOpts, "-"+string(c), arg[j+1:])
						break
					} else if i+1 < len(os.Args) {
						i++
						curlOpts = append(curlOpts, "-"+string(c), os.Args[i])
						break
					} else {
						curlOpts = append(curlOpts, "-"+string(c))
						break
					}
				} else {
					curlOpts = append(curlOpts, "-"+string(c))
				}
			}
			continue
		}

		if method == "" && isMethod(arg) && url == "" {
			method = strings.ToUpper(arg)
			continue
		}
		if url == "" {
			url = arg
			continue
		}

		if idx := strings.Index(arg, ":="); idx != -1 {
			k := arg[:idx]
			v := arg[idx+2:]
			var parsed interface{}
			if err := json.Unmarshal([]byte(v), &parsed); err != nil {
				parsed = nil
			}
			items[k] = parsed
			hasData = true
		} else if idx := strings.Index(arg, "="); idx != -1 {
			k := arg[:idx]
			v := arg[idx+1:]
			items[k] = v
			hasData = true
		} else if idx := strings.Index(arg, ":"); idx != -1 {
			itemsOrHeaders = append(itemsOrHeaders, "-H", arg)
		} else {
			itemsOrHeaders = append(itemsOrHeaders, arg)
		}
	}

	finalCurlOpts := []string{}
	finalCurlOpts = append(finalCurlOpts, curlOpts...)

	if method != "" {
		if method == "HEAD" {
			finalCurlOpts = append(finalCurlOpts, "-I")
		} else {
			finalCurlOpts = append(finalCurlOpts, "-X", method)
		}
	}

	cmdArgs := []string{}
	cmdArgs = append(cmdArgs, finalCurlOpts...)
	cmdArgs = append(cmdArgs, itemsOrHeaders...)

	var requestBody []byte
	if hasData {
		requestBody, _ = json.Marshal(items)
		cmdArgs = append(cmdArgs, "-d", string(requestBody))
	}

	if url != "" {
		cmdArgs = append(cmdArgs, url)
	}

	cmdArgs = append(cmdArgs, "-s", "-S")
	if !hasData {
		if !isTerminal(os.Stdin) {
			cmdArgs = append(cmdArgs, "-d@-")
			cmdArgs = append(cmdArgs, "-H", "Content-Type: application/json")
            if !flagCurl {
                // If it's reading from stdin, read into requestBody so we can print it
                body, err := io.ReadAll(os.Stdin)
                if err == nil {
                    requestBody = body
                }
                // we still pass it to curl! Wait! We just read from os.Stdin! 
                // If we pass -d@-, curl will read from stdin! But we consumed it!
                // So if we read it, we must pass it via pipe or replace `-d@-` with `-d body`!
            }
		}
	} else {
		cmdArgs = append(cmdArgs, "-H", "Content-Type: application/json")
	}
	cmdArgs = append(cmdArgs, "-H", "Accept: application/json, */*")

	displayUrl := url
	if !strings.HasPrefix(url, "http://") && !strings.HasPrefix(url, "https://") && url != "" {
		displayUrl = "http://" + url
	}

	if flagCurl {
		fmt.Fprintln(os.Stderr, displayUrl)
		var sb strings.Builder
		sb.WriteString("curl")
		for _, a := range cmdArgs {
			sb.WriteByte(' ')
			sb.WriteString(shellQuote(a))
		}
		fmt.Fprintln(os.Stdout, sb.String())
		return
	}

	if !flagPretty {
		flagPretty = isTerminal(os.Stdout)
	}

	hasV := false
	for _, a := range finalCurlOpts {
		if a == "-v" || a == "--verbose" {
			hasV = true
			break
		}
	}

    // Wait! We consumed stdin if !flagCurl && !hasData && !isTerminal(os.Stdin).
    // If we did, we must fix cmdArgs because curl will hang reading empty stdin!
    if !hasData && !isTerminal(os.Stdin) && len(requestBody) > 0 {
        for i, a := range cmdArgs {
            if a == "-d@-" {
                cmdArgs[i] = "-d"
                // inject string(requestBody)
                cmdArgs = append(cmdArgs[:i+1], append([]string{string(requestBody)}, cmdArgs[i+1:]...)...)
                break
            }
        }
    }

	if !hasV {
		cmdArgs = append([]string{"-v"}, cmdArgs...)
	}

	fmt.Fprintln(os.Stderr, displayUrl)

	cmd := exec.Command("curl", cmdArgs...)
	stderrPipe, _ := cmd.StderrPipe()
	stdoutPipe, _ := cmd.StdoutPipe()
    cmd.Stdin = os.Stdin

	if err := cmd.Start(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return
	}

	go processStderr(stderrPipe, flagPretty, hasV, requestBody)

	if flagPretty {
		dec := json.NewDecoder(stdoutPipe)
		for {
			var raw json.RawMessage
			err := dec.Decode(&raw)
			if err != nil {
				if buffered, err := io.ReadAll(dec.Buffered()); err == nil {
					os.Stdout.Write(buffered)
				}
				io.Copy(os.Stdout, stdoutPipe)
				break
			}
			os.Stdout.Write(PrettyColor(raw))
		}
	} else {
		io.Copy(os.Stdout, stdoutPipe)
	}

	cmd.Wait()
}
EOF
./compile.sh
"}

